  $top = New-Object System.Windows.Forms.FlowLayoutPanel; $top.Dock = 'Top'; $top.Height = 64; $top.WrapContents = $false; $top.Padding = (& $ui.Pad 32 12 32 0); $top.BackColor = $ui.C.White
  try {
