$steps += @{ Name = 'T21 Import the probe solution r2'; Dir = 'T21'; File = '90161Z-T21-probe-r2.zip'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You import the solution "90-161.Z probe" (3 flows) and select Done. About 8 minutes (estimate).'; Kind = 'guide'; Guide = @('1. On this RADE card, select "Open in browser".', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select Solutions (it can be under More).', '4. Select "Import solution".', '5. Select Browse.', '6. Select the box "File name".', '7. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '8. Select Open.', '9. Select Next.', '10. In each of the 5 connection boxes, select the arrow.', '11. In each list that opens, select your existing connection.', '12. If a box has no connection: select "New connection" in that box.', '13. If you selected "New connection": select Create.', '14. If a sign-in window opens: sign in with your CAC.', '15. If you made a new connection: return to the browser tab where you started the import.', '16. If you made a new connection: select Refresh.', '17. Select Next.', '18. In the box "1 Site URL", type the test site address (it starts with https:// and is the one in the RADE box "Site address").', '19. In the box "3 Shared mailbox", type the e-mail address of your office''s shared mailbox.', '20. Select Import.', '21. Wait for the line "Successfully imported" (1 to 3 minutes, estimate).', '22. Select the solution "90-161.Z probe".', '23. Look at the Status column: the 3 flows "90161Z T21 Probe ..." must read On.', '24. If a flow reads Off: select that flow.', '25. If you selected a flow that reads Off: select "Turn on".', '26. Return to the RADE window.', '27. Select "Done: imported".', 'If the import fails: select "Download log file", then select "It failed" and type the first red error line (no names).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-probe-imported.txt'; Estimate = 480; DoneText = 'Done: imported'; DoneLog = 'Confirmed by you: imported.'; Makes = @(@{ kind = 'solution'; name = '90-161.Z probe (3 flows: Files, Mail, App)' }); After = @('T21 Make the probe list and library r2'); Optional = $false; Help = 'Send the results as they are; the import log step reads the log if you downloaded it.' }
$steps += @{ Name = 'T17 Import log reader r2'; Dir = 'T17'; File = '90161Z-T17-import-log-r2.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 5; Args = ''; Note = 'Runs only if an import failed: copies the error rows of an import log saved in the last 3 hours to T17, addresses masked. Otherwise it reports SKIPPED.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @(); Optional = $false; Help = '' }
$steps += @{ Name = 'T21 Run the flow tests r2'; Dir = 'T21'; File = '90161Z-T21-probe-r2.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = '-Part Run'; Note = 'Signs in (CAC). Starts the 3 flows and waits up to 14 minutes: files (T3, T5), fields (T6), search and members (T7, T8), 3 test e-mails (T9). About 15 minutes (estimate).'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 900; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T21 Import the probe solution r2'); Optional = $false; Help = 'Send the results as they are. A FAILED line is a result of the probe, not a fault of the round.' }
