$steps += @{ Name = 'T21 Look at the draft r2'; Dir = 'T21'; File = '90161Z-T21-links-r2.html'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T2. You open the fake draft and its PDF copy in the browser and post 1 fake comment. About 5 minutes (estimate).'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Select "Open the fake draft".', '3. If a sign-in window opens: sign in with your CAC.', '4. Look at the new tab: the fake draft should open in Word for the web.', '5. If the draft opened in Word for the web: select the tab Review.', '6. If you selected Review: select "New Comment".', '7. In the comment box, type: FAKE COMMENT R26', '8. Press Ctrl+Enter.', '9. In the browser, select the tab "90-161.Z test page".', '10. Select "Open the PDF copy".', '11. Look at the new tab: the PDF should open in the browser.', '12. Return to the RADE window.', '13. Select "Done: I looked".', 'If a link opens an error or nothing: go on with the next step and pick the answer that fits.', 'If the test page is closed: select "Show file in folder", then double-click "90161Z-T21-links-r2.html".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-draft-looked.txt'; Estimate = 300; DoneText = 'Done: I looked'; DoneLog = 'Confirmed by you: looked at the draft.'; Makes = @(); After = @('T21 Open the test page r2', 'T21 Run the flow tests r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 't2-word'; Prompt = 'What did "Open the fake draft" open?'; Kind = 'pick'; Choices = @('Word for the web: I could read it', 'A download of the file', 'An error or a sign-in loop', 'Nothing') }, @{ Key = 't2-comment'; Prompt = 'Could you post the fake comment in Word for the web?'; Kind = 'yesno'; Choices = @() }, @{ Key = 't2-pdf'; Prompt = 'What did "Open the PDF copy" open?'; Kind = 'pick'; Choices = @('The PDF in the browser', 'A download of the PDF', 'Not found', 'An error') }) }
$steps += @{ Name = 'T21 Add a row with a person r2'; Dir = 'T21'; File = '90161Z-T21-links-r2.html'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T7. You add one row in the list form and pick a person in its person box. About 3 minutes (estimate).'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Select "Open the new row form".', '3. In the box "Title", type: T7a', '4. Select the box "ProbePerson".', '5. In the box "ProbePerson", type the first 3 letters of your own last name.', '6. Look at the list under the box: it should show names.', '7. Select your own name in that list.', '8. Select Save.', '9. Return to the RADE window.', '10. Select "Done: row added".', 'If no names show, or your name is not there: select Save, then pick the answer that fits.', 'If the test page is closed: select "Show file in folder", then double-click "90161Z-T21-links-r2.html".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-person-added.txt'; Estimate = 180; DoneText = 'Done: row added'; DoneLog = 'Confirmed by you: row added.'; Makes = @(); After = @('T21 Open the test page r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 't7-search'; Prompt = 'What did the box "ProbePerson" show after 3 letters?'; Kind = 'pick'; Choices = @('Names from the address list', 'Only people of this site', 'No names', 'An error') }, @{ Key = 't7-details'; Prompt = 'Did a name show more than the name, such as an office or an e-mail address?'; Kind = 'yesno'; Choices = @() }) }
