$steps += @{ Name = 'T21 Sign and attach the PDF r2'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T10. You sign the fake PDF with your CAC and attach the signed copy in the list form. About 7 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Look at Acrobat: it shows the fake PDF "FAKE - 90161Z R26 - sign here".', '2. In Acrobat, select "All tools".', '3. Select "Use a certificate".', '4. Select "Digitally sign".', '5. Draw a box on the page with the mouse, where the signature should go.', '6. In the list, select your CAC certificate for signing (not the one for e-mail).', '7. Select Continue.', '8. Select Sign.', '9. Look at Acrobat: it asks where to save the signed copy.', '10. Select the box "File name".', '11. In the box "File name", press Ctrl+V (the path for the signed copy is on the clipboard).', '12. Select Save.', '13. If Windows asks for your PIN: type your CAC PIN.', '14. In the browser, select the tab "90-161.Z test page".', '15. Select "Open the new row form".', '16. In the box "Title", type: T10', '17. Select "Add attachments".', '18. Select the box "File name".', '19. In the box "File name", press Ctrl+V.', '20. Select Open.', '21. Select Save.', '22. Return to the RADE window.', '23. Select "Done: attached".', 'If the PDF opened in the browser and not in Acrobat: select "It failed" and type: opened in the browser'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-signed.txt'; Estimate = 420; DoneText = 'Done: attached'; DoneLog = 'Confirmed by you: signed and attached.'; Makes = @(); After = @('T21 Open the PDF to sign r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 't10-signed'; Prompt = 'Could you sign the fake PDF with your CAC?'; Kind = 'yesno'; Choices = @() }, @{ Key = 't10-attach'; Prompt = 'Could you attach the signed copy in the form?'; Kind = 'yesno'; Choices = @() }) }
$steps += @{ Name = 'T21 Second person r2'; Dir = 'T21'; File = '90161Z-T21-links-r2.html'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T4. A person with only Read on the test site adds one row with the form link you send. About 5 minutes (estimate). If nobody is free today, select Skip.'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Right-click "Open the new row form".', '3. Select "Copy link".', '4. In Teams, open a chat with a person who has only Read on the test site.', '5. In the chat box, press Ctrl+V.', '6. In the chat box, type: Please open this link, type T4a in Title, select Save, and tell me what you saw.', '7. Press Enter.', '8. Wait for the answer of the person in the chat: the row saved, or no permission.', '9. Return to the RADE window.', '10. Select "Done: second person".', 'If nobody is free today: select Skip.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-second-person.txt'; Estimate = 300; DoneText = 'Done: second person'; DoneLog = 'Confirmed by you: second person.'; Makes = @(); After = @('T21 Open the test page r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 't4-second'; Prompt = 'What did the second person see?'; Kind = 'pick'; Choices = @('The row was saved', 'No permission', 'The link did not open', 'Something else') }) }
