$steps += @{ Name = 'T21 Check your e-mail r2'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'Test T9. You look for the 3 test e-mails in your Inbox and in Junk Email. About 3 minutes (estimate).'; Kind = 'guide'; Guide = @('1. Open Outlook (the program on your computer).', '2. Select the folder Inbox.', '3. In the search box at the top, type: 90161Z T9', '4. Press Enter.', '5. Look at the subjects found: each one has S3, S5 or S6 in it.', 'If nothing is found: that is a result; go on with the next step.', '6. Select the folder "Junk Email".', '7. In the search box at the top, type: 90161Z T9', '8. Press Enter.', '9. Look at the subjects found.', '10. Return to the RADE window.', '11. Select "Done: I looked".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-mail-looked.txt'; Estimate = 180; DoneText = 'Done: I looked'; DoneLog = 'Confirmed by you: looked for the test e-mails.'; Makes = @(); After = @('T21 Run the flow tests r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 't9-inbox'; Prompt = 'Which test e-mails are in your Inbox? Type S3, S5 or S6 (one or more), or none.'; Kind = 'text'; Choices = @() }, @{ Key = 't9-junk'; Prompt = 'Which test e-mails are in Junk Email? Type S3, S5 or S6 (one or more), or none.'; Kind = 'text'; Choices = @() }, @{ Key = 't9-blocked'; Prompt = 'Did Outlook or an e-mail tell you that a message was blocked or quarantined?'; Kind = 'yesno'; Choices = @() }) }
